    35
    36  extern "C" int LLVMFuzzerTestOneInput(const uint8_t* Data, size_t Size) {
    37    assert(Data);
    38
    39    try {
    40      const rawspeed::Buffer b(Data, Size);
    41      const rawspeed::DataBuffer db(b, rawspeed::Endianness::little);
    42      rawspeed::ByteStream bs(db);
    43
    44      rawspeed::RawImage mRaw(CreateRawImage(&bs));
    45
    46      const auto numStrips = bs.getU32();
    47      std::vector<rawspeed::PhaseOneStrip> strips;
    48      std::generate_n(std::back_inserter(strips), numStrips,
    49                      [&bs]() -> rawspeed::PhaseOneStrip {
    50                        const int n = bs.getU32();
    51                        const auto stripLen = bs.getU32();
    52                        return {n, bs.getStream(stripLen)};
    53                      });
    54      assert(strips.size() == numStrips);
    55
    56      rawspeed::PhaseOneDecompressor f(mRaw, std::move(strips));
    57      mRaw->createData();
    58      f.decompress();
    59
    60      mRaw->checkMemIsInitialized();
    61    } catch (rawspeed::RawspeedException&) {
    62      // Exceptions are good, crashes are bad.
    63    }
    64
    65    return 0;
    66  }

